import React, {useEffect, useState} from 'react';
import { MatrixInput } from './MatrixInput';
import { MatrixTextInput } from './MatrixTextInput';
import { FileUpload } from './FileUpload';
import { ResultsDisplay } from './ResultsDisplay';
import { IterationTable } from './IterationTable';

import { lab1Api } from '../../services/api';
import { SolutionResponse } from '../../types';
import toast from 'react-hot-toast';

type InputMode = 'manual' | 'text' | 'file';

export const SLAUPage: React.FC = () => {
    const [n, setN] = useState<number>(3);
    const [inputMode, setInputMode] = useState<InputMode>('manual');
    const [matrix, setMatrix] = useState<number[][]>(
        Array(3).fill(0).map(() => Array(3).fill(0))
    );
    const [vector, setVector] = useState<number[]>(Array(3).fill(0));
    const [epsilon, setEpsilon] = useState<number>(0.000001);
    const [maxIterations, setMaxIterations] = useState<number>(100);
    const [loading, setLoading] = useState<boolean>(false);
    const [result, setResult] = useState<SolutionResponse | null>(null);

    // Функция обновления данных (вызывается из всех подкомпонентов)
    useEffect(() => {
        // Эта логика срабатывает ТОЛЬКО при изменении n
        // Она сохраняет старые данные, обрезая лишнее или дополняя нулями
        setMatrix(prevMatrix => {
            const newMatrix = Array(n).fill(0).map((_, i) => {
                return Array(n).fill(0).map((_, j) => {
                    // Если элемент существовал в старой матрице — сохраняем его
                    return (prevMatrix[i] && prevMatrix[i][j] !== undefined)
                        ? prevMatrix[i][j]
                        : 0;
                });
            });
            return newMatrix;
        });

        setVector(prevVector => {
            return Array(n).fill(0).map((_, i) => {
                return (prevVector[i] !== undefined) ? prevVector[i] : 0;
            });
        });

        setResult(null);
    }, [n]);

    const updateData = (newMatrix: number[][], newVector: number[]) => {
        setMatrix(newMatrix);
        setVector(newVector);
        setN(newMatrix.length);
        setResult(null);
    };

    const handleSolve = async () => {
        setLoading(true);
        try {
            const response = await lab1Api.solve({
                matrix,
                vector,
                params: { epsilon, maxIterations }
            });
            setResult(response.data);
            if (response.data.status === 'success') {
                toast.success('Выполнено');
            } else {
                toast.error(response.data.message);
            }
        } catch (error: any) {
            toast.error('Ошибка соединения с сервером');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mx-auto px-4 py-6 max-w-5xl font-sans text-slate-800">
            {/* Header - строгий */}
            <div className="mb-6 border-b pb-4 flex justify-between items-end">
                <div>
                    <h1 className="text-xl font-bold uppercase tracking-tight">Лабораторная работа №1</h1>
                    <p className="text-sm text-slate-500">Метод Гаусса-Зейделя | Вариант 20</p>
                </div>
                <div className="text-right text-xs text-slate-400">
                    <p>Ясаков А. А. | P3213</p>
                    <p>ИСУ: 468198</p>
                </div>
            </div>

            {/* Input Section */}
            <div className="bg-white border shadow-sm mb-8">
                <div className="p-4 border-b bg-slate-50 flex items-center justify-between">
                    <div className="flex gap-6 items-center">
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-slate-500 uppercase">Размер:</span>
                            <input
                                type="number"
                                value={n}
                                onChange={(e) => {
                                    const val = Math.min(Math.max(parseInt(e.target.value) || 1, 1), 20);
                                    setN(val);
                                }}
                                className="w-12 border px-1 py-0.5 text-center focus:outline-none focus:border-slate-400"
                            />
                        </div>
                        <div className="flex items-center gap-2 border-l pl-6">
                            <span className="text-xs font-bold text-slate-500 uppercase">Точность:</span>
                            <input
                                type="number"
                                step="0.00001"
                                value={epsilon}
                                onChange={(e) => setEpsilon(parseFloat(e.target.value))}
                                className="w-24 border px-1 py-0.5 text-center focus:outline-none focus:border-slate-400"
                            />
                        </div>
                    </div>

                    <div className="flex border rounded overflow-hidden">
                        {(['manual', 'text', 'file'] as InputMode[]).map((mode) => (
                            <button
                                key={mode}
                                onClick={() => setInputMode(mode)}
                                className={`px-4 py-1.5 text-xs font-bold uppercase transition-colors ${
                                    inputMode === mode ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 hover:bg-slate-100'
                                }`}
                            >
                                {mode === 'manual' ? 'Таблица' : mode === 'text' ? 'Текст' : 'Файл'}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="p-6">
                    <div className="overflow-x-auto min-h-[200px]">
                        {inputMode === 'manual' && (
                            <MatrixInput n={n} matrix={matrix} vector={vector} onChange={updateData} />
                        )}
                        {inputMode === 'text' && (
                            <MatrixTextInput n={n} matrix={matrix} vector={vector} onChange={updateData} />
                        )}
                        {inputMode === 'file' && (
                            <FileUpload onDataLoaded={(data) => updateData(data.matrix, data.vector)} />
                        )}
                    </div>

                    <button
                        onClick={handleSolve}
                        disabled={loading}
                        className="mt-6 w-full py-3 bg-slate-800 hover:bg-black text-white font-bold uppercase tracking-widest transition-all disabled:bg-slate-300"
                    >
                        {loading ? 'Вычисление...' : 'Запустить расчет'}
                    </button>
                </div>
            </div>

            {/* Results Section */}
            <div className="space-y-6">
                {result ? (
                    <div className="border-t-2 border-slate-800 pt-8 animate-in fade-in duration-700">
                        <h2 className="text-lg font-bold uppercase mb-6 tracking-widest">Отчет о решении</h2>

                        {result.status === 'error' ? (
                            <div className="p-4 bg-red-50 border border-red-200 text-red-700 text-sm font-medium">
                                Ошибка: {result.message}
                            </div>
                        ) : (
                            <div className="space-y-10">
                                <ResultsDisplay result={result} />
                                <div className="pt-6 border-t border-dashed">
                                    <h3 className="text-sm font-bold uppercase text-slate-500 mb-4">История итераций</h3>
                                    <IterationTable history={result.iterationHistory} solution={result.solution} />
                                </div>
                            </div>
                        )}
                    </div>
                ) : (
                    <div className="py-12 text-center text-slate-300 uppercase tracking-widest text-xs border-2 border-dashed">
                        Ожидание ввода данных
                    </div>
                )}
            </div>
        </div>
    );
};
